CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, mode text NOT NULL CHECK(mode IN ('demo','live')),
 clock_at timestamptz, paused boolean NOT NULL DEFAULT false, budget_limit integer NOT NULL DEFAULT 100, budget_used integer NOT NULL DEFAULT 0,
 brand jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), CHECK(mode = 'demo' OR clock_at IS NULL)
);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(org_id uuid REFERENCES organizations(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('owner','editor','approver','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE entities(org_id uuid REFERENCES organizations(id) ON DELETE CASCADE,id uuid NOT NULL DEFAULT gen_random_uuid(),kind text NOT NULL,data jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE INDEX entities_kind ON entities(org_id,kind);
CREATE TABLE connections(org_id uuid REFERENCES organizations(id) ON DELETE CASCADE,id uuid NOT NULL DEFAULT gen_random_uuid(),channel text NOT NULL CHECK(channel IN('instagram','youtube','linkedin')),account_id text NOT NULL,account_name text NOT NULL,status text NOT NULL DEFAULT 'demo',paused boolean NOT NULL DEFAULT false,capabilities jsonb NOT NULL DEFAULT '{}',tokens_encrypted text,api_version text,scopes text[] NOT NULL DEFAULT '{}',last_health_at timestamptz,PRIMARY KEY(org_id,id),UNIQUE(org_id,channel,account_id));
CREATE TABLE variants(org_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,id uuid NOT NULL DEFAULT gen_random_uuid(),brief_id uuid,channel text NOT NULL,connection_id uuid NOT NULL,current_revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'rendering',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,connection_id) REFERENCES connections(org_id,id));
CREATE TABLE variant_revisions(org_id uuid NOT NULL,variant_id uuid NOT NULL,revision integer NOT NULL,copy jsonb NOT NULL,asset_ids uuid[] NOT NULL DEFAULT '{}',created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,variant_id,revision),FOREIGN KEY(org_id,variant_id) REFERENCES variants(org_id,id) ON DELETE CASCADE);
CREATE TABLE approvals(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),variant_id uuid NOT NULL,revision integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),snapshot_hash text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),invalidated_at timestamptz,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,variant_id,revision) REFERENCES variant_revisions(org_id,variant_id,revision));
CREATE TABLE deliveries(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),variant_id uuid NOT NULL,revision integer NOT NULL,approval_id uuid NOT NULL,connection_id uuid NOT NULL,status text NOT NULL CHECK(status IN('scheduled','dispatching','processing','published','manual','cancelled','expired','blocked','failed','outcome_unknown')),scheduled_at timestamptz NOT NULL,timezone text NOT NULL,expires_at timestamptz NOT NULL,grace_seconds integer NOT NULL DEFAULT 3600,remote_id text,error text,lease_token uuid,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,approval_id) REFERENCES approvals(org_id,id),FOREIGN KEY(org_id,connection_id) REFERENCES connections(org_id,id),FOREIGN KEY(org_id,variant_id,revision) REFERENCES variant_revisions(org_id,variant_id,revision));
CREATE UNIQUE INDEX one_active_delivery ON deliveries(org_id,variant_id) WHERE status IN('scheduled','dispatching','processing','outcome_unknown');
CREATE INDEX deliveries_due ON deliveries(scheduled_at) WHERE status='scheduled';
CREATE TABLE attempts(org_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),delivery_id uuid NOT NULL,lease_token uuid NOT NULL,state text NOT NULL,remote_id text,detail jsonb NOT NULL DEFAULT '{}',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,delivery_id) REFERENCES deliveries(org_id,id));
CREATE TABLE receipts(org_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),delivery_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('demo','api','manual')),remote_id text NOT NULL,permalink text,visibility text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,delivery_id),FOREIGN KEY(org_id,delivery_id) REFERENCES deliveries(org_id,id));
CREATE TABLE demo_external_posts(org_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),delivery_id uuid NOT NULL,channel text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,delivery_id));
CREATE TABLE jobs(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','complete','dead')),attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 4,run_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,last_error text,dedupe_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,dedupe_key));
CREATE INDEX jobs_due ON jobs(run_at,created_at) WHERE status IN('pending','running');
CREATE TABLE conversations(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),connection_id uuid NOT NULL,external_id text NOT NULL,kind text NOT NULL CHECK(kind IN('private','comment')),language text NOT NULL DEFAULT 'en',last_inbound_at timestamptz,last_human_reply_at timestamptz,version integer NOT NULL DEFAULT 0,opted_out boolean NOT NULL DEFAULT false,PRIMARY KEY(org_id,id),UNIQUE(org_id,connection_id,external_id),FOREIGN KEY(org_id,connection_id) REFERENCES connections(org_id,id));
CREATE TABLE messages(org_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,external_id text NOT NULL,direction text NOT NULL CHECK(direction IN('inbound','human','agent')),text text NOT NULL,observed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),UNIQUE(org_id,conversation_id,external_id),FOREIGN KEY(org_id,conversation_id) REFERENCES conversations(org_id,id) ON DELETE CASCADE);
CREATE TABLE reply_drafts(org_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,conversation_version integer NOT NULL,text text NOT NULL,evidence_ids uuid[] NOT NULL DEFAULT '{}',status text NOT NULL CHECK(status IN('review','approved','sent','stale','escalated','suppressed','outcome_unknown','blocked')),expires_at timestamptz NOT NULL,approved_by uuid REFERENCES users(id),approved_at timestamptz,sent_at timestamptz,reason text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,conversation_id) REFERENCES conversations(org_id,id));
CREATE UNIQUE INDEX one_current_reply ON reply_drafts(org_id,conversation_id) WHERE status IN('review','approved');
CREATE TABLE inbox_events(org_id uuid NOT NULL,connection_id uuid NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,connection_id,event_id),FOREIGN KEY(org_id,connection_id) REFERENCES connections(org_id,id));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),action text NOT NULL,target_id uuid,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_time ON audit_events(org_id,created_at DESC);
CREATE TABLE observations(org_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL DEFAULT gen_random_uuid(),source text NOT NULL,external_id text NOT NULL,topic text NOT NULL,kind text NOT NULL,region text NOT NULL DEFAULT 'unknown',language text NOT NULL DEFAULT 'en',metric numeric NOT NULL,observed_at timestamptz NOT NULL,collected_at timestamptz NOT NULL DEFAULT now(),url text,provenance jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(org_id,id),UNIQUE(org_id,source,external_id));
CREATE TABLE source_cursors(org_id uuid NOT NULL REFERENCES organizations(id),source text NOT NULL,cursor text,last_success_at timestamptz,last_error text,config jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(org_id,source));
CREATE TABLE worker_health(id text PRIMARY KEY,last_seen_at timestamptz NOT NULL,detail jsonb NOT NULL DEFAULT '{}');
CREATE OR REPLACE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable record cannot be changed'; END; $$;
CREATE TRIGGER immutable_revision BEFORE UPDATE ON variant_revisions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
